import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.cbrt
import kotlin.math.sqrt

class FenwickTree(n: Int) {
    private val `val`: LongArray = LongArray(n + 1)

    fun add(xInput: Int, v: Long) {
        var x = xInput
        while (x < `val`.size) {
            `val`[x] += v
            x += x and -x
        }
    }

    fun sum(xInput: Int): Long {
        var x = xInput
        require(x < `val`.size)
        var ans = 0L
        while (x > 0) {
            ans += `val`[x]
            x -= x and -x
        }
        return ans
    }
}

fun sieve(n: Int): LongArray {
    val isPrime = BooleanArray(n + 1) { true }
    var i = 2
    while (true) {
        if (i * i > n) break
        if (isPrime[i]) {
            var j = i * i
            while (j <= n) {
                isPrime[j] = false
                j += i
            }
        }
        i++
    }
    val len = isPrime.asSequence().drop(2).count { it }
    val prime = LongArray(len)
    var idx = 0
    for (k in 2..n) {
        if (isPrime[k]) {
            prime[idx++] = k.toLong()
        }
    }
    return prime
}

class PrimeCountSolver {
    private val query = ArrayList<Long>()
    private var memo = LongArray(0)

    fun add(n: Long) {
        query.add(n)
    }

    fun build() {
        query.sort()
        val deduped = ArrayList<Long>()
        var last: Long? = null
        for (v in query) {
            if (last == null || last != v) {
                deduped.add(v)
                last = v
            }
        }
        query.clear()
        query.addAll(deduped)

        val n = query.lastOrNull() ?: 1L
        var m = 1L
        while ((m + 1) * (m + 1) <= n) {
            m++
        }
        val p = sieve(m.toInt())
        val bound = cbrt(n.toDouble()).let { it * it }.toLong() + 2

        val stack = ArrayList<Pair<Long, Int>>()
        for (v in query) {
            val k = run {
                var left = 0
                var right = p.size
                while (left < right) {
                    val mid = (left + right) ushr 1
                    val cmp = (p[mid] * p[mid]).compareTo(v)
                    if (cmp < 0) left = mid + 1 else right = mid
                }
                if (left < p.size && p[left] * p[left] == v) left + 1 else left
            }
            stack.add(Pair(v, k))
        }

        val queryPairs = ArrayList<Pair<Int, Long>>()
        while (stack.isNotEmpty()) {
            val (nn, kk) = stack.removeAt(stack.size - 1)
            var n2 = nn
            var k2 = kk
            if (k2 == 0) continue
            val q = p[k2 - 1]
            if (q * q > n2) {
                val x = run {
                    var left = 0
                    var right = k2
                    while (left < right) {
                        val mid = (left + right) ushr 1
                        val cmp = (p[mid] * p[mid]).compareTo(n2)
                        if (cmp < 0) left = mid + 1 else right = mid
                    }
                    if (left < k2 && p[left] * p[left] == n2) left + 1 else left
                }
                stack.add(Pair(n2, x))
            } else if (n2 <= bound) {
                queryPairs.add(Pair(k2, n2))
            } else {
                stack.add(Pair(n2, k2 - 1))
                stack.add(Pair(n2 / q, k2 - 1))
            }
        }

        queryPairs.sortWith(compareBy({ it.first }, { it.second }))
        val dedupQP = ArrayList<Pair<Int, Long>>()
        var lastQP: Pair<Int, Long>? = null
        for (v in queryPairs) {
            if (lastQP == null || lastQP != v) {
                dedupQP.add(v)
                lastQP = v
            }
        }

        val mInt = bound.toInt()
        val bit = FenwickTree(mInt)
        for (i2 in 1..mInt) {
            bit.add(i2, 1L)
        }
        val isPrime = BooleanArray(mInt + 1) { true }
        val memoLocal = LongArray(dedupQP.size)
        var pos = 0
        for ((i2, pp) in p.withIndex()) {
            val primeVal = pp.toInt()
            var j = primeVal
            while (j <= mInt) {
                if (isPrime[j]) {
                    bit.add(j, -1L)
                }
                isPrime[j] = false
                j += primeVal
            }
            while (pos < dedupQP.size) {
                val (k2, n2) = dedupQP[pos]
                if (k2 > i2 + 1) break
                memoLocal[pos] = bit.sum(n2.toInt())
                pos++
            }
            if (pos >= dedupQP.size) break
        }

        memo = LongArray(query.size)
        val stack2 = ArrayList<Quad>()
        for ((i2, nn) in query.withIndex()) {
            val k = run {
                var left = 0
                var right = p.size
                while (left < right) {
                    val mid = (left + right) ushr 1
                    val cmp = (p[mid] * p[mid]).compareTo(nn)
                    if (cmp < 0) left = mid + 1 else right = mid
                }
                if (left < p.size && p[left] * p[left] == nn) left + 1 else left
            }
            memo[i2] += k.toLong() - 1
            stack2.add(Quad(nn, k, 1L, i2))
        }

        while (stack2.isNotEmpty()) {
            val (nn, kk, sign, idx) = stack2.removeAt(stack2.size - 1)
            var n2 = nn
            var k2 = kk
            if (k2 == 0) {
                memo[idx] += sign * n2
                continue
            }
            val q = p[k2 - 1]
            if (q * q > n2) {
                val x = run {
                    var left = 0
                    var right = k2
                    while (left < right) {
                        val mid = (left + right) ushr 1
                        val cmp = (p[mid] * p[mid]).compareTo(n2)
                        if (cmp < 0) left = mid + 1 else right = mid
                    }
                    if (left < k2 && p[left] * p[left] == n2) left + 1 else left
                }
                memo[idx] += -sign * (k2 - x).toLong()
                stack2.add(Quad(n2, x, sign, idx))
            } else if (n2 <= bound) {
                val pos2 = dedupQP.binarySearch(Pair(k2, n2), compareBy({ it.first }, { it.second }))
                memo[idx] += sign * memoLocal[pos2]
            } else {
                stack2.add(Quad(n2, k2 - 1, sign, idx))
                stack2.add(Quad(n2 / q, k2 - 1, -sign, idx))
            }
        }
    }

    fun get(n: Long): Long {
        val idx = query.binarySearch(n)
        return memo[idx]
    }

    private data class Quad(val n: Long, val k: Int, val sign: Long, val idx: Int)
}

fun run() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val s = br.readLine()
    val n = s.trim().toLong()
    val p = sieve(sqrt(n.toDouble()).toInt() + 2)
    var ans = 0L
    for (pp in p) {
        if (pp * pp * pp <= n) {
            ans++
        } else {
            break
        }
    }
    val solver = PrimeCountSolver()
    for ((i, pp) in p.withIndex()) {
        if (pp * pp <= n) {
            ans -= i.toLong() + 1
            solver.add(n / pp)
        }
    }
    solver.build()
    for (pp in p) {
        if (pp * pp <= n) {
            ans += solver.get(n / pp)
        }
    }
    println(ans)
}

fun main() {
    run()
}

